package main

import (
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
)

var (
	db          *sql.DB
	sessionsMu  sync.RWMutex
	sessions    = make(map[string]*UserSession)
	dataDir     string
)

const (
	MaxPageSize    = 100
	MaxTotalItems  = 10000
	SessionTimeout = 30 * time.Minute
)

type UserSession struct {
	UserID    string
	Role      string
	CreatedAt time.Time
}

type DocumentMeta struct {
	ID       string `json:"id"`
	Title    string `json:"title"`
	Owner    string `json:"owner"`
	Classify string `json:"classification"`
}

type PaginatedResponse struct {
	Documents []DocumentMeta `json:"documents"`
	Total     int            `json:"total"`
	Page      int            `json:"page"`
	PageSize  int            `json:"page_size"`
}

func init() {
	var err error
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		log.Fatal("DATABASE_URL required")
	}
	db, err = sql.Open("postgres", dbURL)
	if err != nil {
		log.Fatal(err)
	}
	dataDir = os.Getenv("DATA_DIR")
	if dataDir == "" {
		dataDir = "/var/app/documents"
	}
}

func generateToken() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return hex.EncodeToString(b)
}

func hashSessionID(token string) string {
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:])
}

func authenticateRequest(r *http.Request) *UserSession {
	cookie, err := r.Cookie("session")
	if err != nil {
		return nil
	}
	hashed := hashSessionID(cookie.Value)
	sessionsMu.RLock()
	defer sessionsMu.RUnlock()
	sess, ok := sessions[hashed]
	if !ok || time.Since(sess.CreatedAt) > SessionTimeout {
		return nil
	}
	return sess
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var creds struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&creds); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	var storedHash string
	var userID, role string
	err := db.QueryRow("SELECT id, password_hash, role FROM users WHERE username = $1",
		creds.Username).Scan(&userID, &storedHash, &role)
	if err != nil {
		// Constant-time-ish: always do a bcrypt compare even on not-found
		bcrypt.CompareHashAndPassword([]byte("$2a$10$xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"), []byte(creds.Password))
		time.Sleep(100 * time.Millisecond)
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	if err := bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(creds.Password)); err != nil {
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	token := generateToken()
	hashed := hashSessionID(token)
	sessionsMu.Lock()
	sessions[hashed] = &UserSession{UserID: userID, Role: role, CreatedAt: time.Now()}
	sessionsMu.Unlock()

	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    token,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
		MaxAge:   1800,
	})
	w.WriteHeader(http.StatusOK)
}

// computeOffset calculates the database offset for pagination.
// Uses int arithmetic for performance - page and pageSize are
// validated to be positive before this is called.
func computeOffset(page, pageSize int) int {
	return (page - 1) * pageSize
}

// validatePagination ensures page and pageSize are within acceptable bounds.
// Returns validated page, pageSize, or error.
func validatePagination(pageStr, pageSizeStr string) (int, int, error) {
	page, err := strconv.Atoi(pageStr)
	if err != nil || page < 1 {
		page = 1
	}
	pageSize, err := strconv.Atoi(pageSizeStr)
	if err != nil || pageSize < 1 {
		pageSize = 20
	}
	if pageSize > MaxPageSize {
		pageSize = MaxPageSize
	}
	// Ensure we don't exceed maximum total items
	// This check prevents requesting pages beyond the allowed range
	offset := computeOffset(page, pageSize)
	if offset < 0 || offset > MaxTotalItems {
		return 0, 0, fmt.Errorf("page out of range")
	}
	return page, pageSize, nil
}

func handleDocumentList(w http.ResponseWriter, r *http.Request) {
	sess := authenticateRequest(r)
	if sess == nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	pageStr := r.URL.Query().Get("page")
	pageSizeStr := r.URL.Query().Get("page_size")

	page, pageSize, err := validatePagination(pageStr, pageSizeStr)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	offset := computeOffset(page, pageSize)

	// Build query based on role
	var query string
	var args []interface{}
	if sess.Role == "admin" {
		query = "SELECT id, title, owner, classification FROM documents ORDER BY created_at DESC LIMIT $1 OFFSET $2"
		args = []interface{}{pageSize, offset}
	} else {
		query = "SELECT id, title, owner, classification FROM documents WHERE owner = $1 OR classification = 'public' ORDER BY created_at DESC LIMIT $2 OFFSET $3"
		args = []interface{}{sess.UserID, pageSize, offset}
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []DocumentMeta
	for rows.Next() {
		var doc DocumentMeta
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Owner, &doc.Classify); err != nil {
			continue
		}
		docs = append(docs, doc)
	}

	resp := PaginatedResponse{
		Documents: docs,
		Total:     len(docs),
		Page:      page,
		PageSize:  pageSize,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// handleDocumentDownload serves document files with path traversal protection
func handleDocumentDownload(w http.ResponseWriter, r *http.Request) {
	sess := authenticateRequest(r)
	if sess == nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	docID := r.URL.Query().Get("id")
	if docID == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}

	// Validate document ID format - alphanumeric and hyphens only
	for _, c := range docID {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-') {
			http.Error(w, "invalid document id", http.StatusBadRequest)
			return
		}
	}

	// Check ownership/access in database
	var owner, classification string
	err := db.QueryRow("SELECT owner, classification FROM documents WHERE id = $1", docID).Scan(&owner, &classification)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	if sess.Role != "admin" && owner != sess.UserID && classification != "public" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	// Construct safe file path
	filePath := filepath.Join(dataDir, docID+".pdf")
	cleanPath := filepath.Clean(filePath)
	if !strings.HasPrefix(cleanPath, filepath.Clean(dataDir)+string(os.PathSeparator)) {
		http.Error(w, "invalid path", http.StatusBadRequest)
		return
	}

	http.ServeFile(w, r, cleanPath)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/login", handleLogin)
	mux.HandleFunc("/api/documents", handleDocumentList)
	mux.HandleFunc("/api/documents/download", handleDocumentDownload)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	certFile := os.Getenv("TLS_CERT")
	keyFile := os.Getenv("TLS_KEY")
	if certFile == "" || keyFile == "" {
		log.Fatal("TLS_CERT and TLS_KEY required")
	}
	log.Fatal(server.ListenAndServeTLS(certFile, keyFile))
}
